import { expect, test } from "vitest";
import { onHalfHour } from "../../src/modules/bookings/bookings.service.ts";

test("onHalfHour accepts the hour and the half hour", () => {
  // Arrange: two times on the boundary.
  const onTheHour = new Date("2026-10-05T14:00:00Z");
  const halfPast = new Date("2026-10-05T14:30:00Z");

  // Act and assert: call the function, and check what it returns.
  expect(onHalfHour(onTheHour)).toBe(true);
  expect(onHalfHour(halfPast)).toBe(true);
});

test("onHalfHour rejects anything in between", () => {
  expect(onHalfHour(new Date("2026-10-05T14:10:00Z"))).toBe(false);
});

import { describe, expect, it } from "vitest";
import { ConflictError, UnprocessableError } from "../../src/domain/errors.ts";
import { createInMemoryBookingRepository } from "../../src/modules/bookings/bookings.repository.ts";
import { createBookingService } from "../../src/modules/bookings/bookings.service.ts";
import { clock, testRooms } from "../support/app.ts";

const at = (iso: string) => new Date(iso);
const valid = {
  roomId: 1,
  userId: 1,
  startsAt: at("2026-10-05T14:00:00Z"),
  endsAt: at("2026-10-05T15:30:00Z"),
  attendees: 3,
  note: null,
};

function setup() {
  const bookings = createInMemoryBookingRepository(clock);
  const service = createBookingService({ bookings, rooms: testRooms(), clock });
  return { service, bookings };
}

describe("the booking service's create", () => {
  it("saves a valid booking for the caller", async () => {
    const { service, bookings } = setup();

    const booking = await service.create(valid);

    expect(booking).toMatchObject({ id: 1001, userId: 1, roomId: 1, status: "confirmed" });
    expect(booking.createdAt).toEqual(at("2026-10-01T09:00:00Z"));
    expect(await bookings.findById(1001)).toEqual(booking);
  });

  it.each([
    ["starts off the half hour", { startsAt: at("2026-10-05T14:10:00Z") }, "startsAt"],
    ["lasts under 30 minutes", { endsAt: at("2026-10-05T14:00:00Z") }, "endsAt"],
    ["lasts over 3 hours", { endsAt: at("2026-10-05T17:30:00Z") }, "endsAt"],
    ["starts in the past", { startsAt: at("2026-09-30T14:00:00Z"), endsAt: at("2026-09-30T15:00:00Z") }, "startsAt"],
    ["starts over 14 days ahead", { startsAt: at("2026-10-16T14:00:00Z"), endsAt: at("2026-10-16T15:00:00Z") }, "startsAt"],
    ["has more people than seats", { attendees: 7 }, "attendees"],
  ])("rejects a booking that %s", async (_why, change, field) => {
    const { service, bookings } = setup();

    const error = await service.create({ ...valid, ...change }).catch((e: unknown) => e);

    expect(error).toBeInstanceOf(UnprocessableError);
    expect((error as UnprocessableError).errors.map((e) => e.field)).toContain(field);
    expect(await bookings.countUpcoming(1, clock())).toBe(0);
  });

  it("refuses a fourth upcoming booking", async () => {
    const { service } = setup();
    for (const day of ["05", "06", "07"]) {
      await service.create({ ...valid, startsAt: at(`2026-10-${day}T14:00:00Z`), endsAt: at(`2026-10-${day}T15:00:00Z`) });
    }

    const fourth = { ...valid, startsAt: at("2026-10-08T14:00:00Z"), endsAt: at("2026-10-08T15:00:00Z") };
    await expect(service.create(fourth)).rejects.toThrow(ConflictError);
  });
});

import { expect, it, vi } from "vitest";
import type { BookingRepository } from "../../src/modules/bookings/bookings.repository.ts";
import { createBookingService } from "../../src/modules/bookings/bookings.service.ts";
import { clock, testRooms } from "../support/app.ts";

it("checks Ada's upcoming bookings at the clock's time, then saves hers", async () => {
  const bookings = {
    findById: vi.fn(),
    insert: vi.fn(async (b) => ({ ...b, id: 1001, status: "confirmed" as const, version: 1, createdAt: clock() })),
    countUpcoming: vi.fn(async () => 0),
  } satisfies BookingRepository;
  const service = createBookingService({ bookings, rooms: testRooms(), clock });

  await service.create({
    roomId: 1,
    userId: 1,
    startsAt: new Date("2026-10-05T14:00:00Z"),
    endsAt: new Date("2026-10-05T15:30:00Z"),
    attendees: 3,
    note: null,
  });

  expect(bookings.countUpcoming).toHaveBeenCalledWith(1, new Date("2026-10-01T09:00:00Z"));
  expect(bookings.insert).toHaveBeenCalledOnce();
  expect(bookings.insert).toHaveBeenCalledWith(expect.objectContaining({ userId: 1, roomId: 1 }));
});

import { createApp } from "../../src/app.ts";
import { ROLE_SCOPES, type Role } from "../../src/modules/auth/principal.ts";
import { createAccessTokens } from "../../src/modules/auth/tokens.ts";
import { createUserDirectory } from "../../src/modules/auth/users.ts";
import { createInMemoryBookingRepository, type BookingRepository } from "../../src/modules/bookings/bookings.repository.ts";
import { createBookingService } from "../../src/modules/bookings/bookings.service.ts";
import { createInMemoryRoomRepository, type RoomRepository } from "../../src/modules/rooms/rooms.repository.ts";

/** Roombook's fixed time: Thursday 2026-10-01, 09:00 UTC. */
export const clock = () => new Date("2026-10-01T09:00:00Z");
export const TEST_SECRET = "cm9vbWJvb2sgdGVzdCBzZWNyZXQsIDMyIGJ5dGVzISE";
const tokens = createAccessTokens(TEST_SECRET);

export const ada = { id: 1, role: "member", buildingId: null } as const;

export const testRooms = () =>
  createInMemoryRoomRepository([
    { id: 1, name: "Turing", building: "main-library", capacity: 6, amenities: ["whiteboard", "screen"] },
    { id: 2, name: "Lovelace", building: "main-library", capacity: 4, amenities: ["whiteboard"] },
  ]);

/** The real app, with in-memory repositories unless a test passes its own, and the fixed clock. */
export function testApp(repos: { rooms?: RoomRepository; bookings?: BookingRepository } = {}) {
  const rooms = repos.rooms ?? testRooms();
  const bookings = repos.bookings ?? createInMemoryBookingRepository(clock);
  return createApp({
    bookingService: createBookingService({ bookings, rooms, clock }),
    rooms,
    users: createUserDirectory(),
    tokens,
  });
}

/** An Authorization header for a user, signed the way the app signs tokens. */
export async function bearer(user: { id: number; role: Role; buildingId: number | null }) {
  return `Bearer ${await tokens.issue(user, ROLE_SCOPES[user.role])}`;
}

import request from "supertest";
import { describe, expect, it } from "vitest";
import { ada, bearer, testApp } from "../support/app.ts";

const booking = { roomId: 1, startsAt: "2026-10-05T14:00:00Z", endsAt: "2026-10-05T15:30:00Z", attendees: 3 };

describe("POST /v1/bookings", () => {
  it("creates the booking and says where it lives", async () => {
    const res = await request(testApp())
      .post("/v1/bookings")
      .set("Authorization", await bearer(ada))
      .send(booking);

    expect(res.status).toBe(201);
    expect(res.headers.location).toBe("/v1/bookings/1001");
    expect(res.body).toMatchObject({ id: 1001, userId: 1, status: "confirmed", startsAt: "2026-10-05T14:00:00Z" });
  });

  it("answers 401 and a problem without a token", async () => {
    const res = await request(testApp()).post("/v1/bookings").send(booking);

    expect(res.status).toBe(401);
    expect(res.headers["www-authenticate"]).toBe('Bearer realm="roombook"');
    expect(res.type).toBe("application/problem+json");
    expect(res.body.type).toBe("https://roombook.example/problems/unauthorized");
  });

  it("reports every invalid field at once", async () => {
    const res = await request(testApp())
      .post("/v1/bookings")
      .set("Authorization", await bearer(ada))
      .send({ ...booking, startsAt: "2026-10-05T14:10:00Z", attendees: 9 });

    expect(res.status).toBe(422);
    expect(res.body.errors).toEqual([
      { field: "startsAt", message: "must be on the hour or half past" },
      { field: "attendees", message: "Turing holds at most 6 people" },
    ]);
  });

  it("answers 409 when the room is already taken", async () => {
    const app = testApp();
    const auth = await bearer(ada);
    await request(app).post("/v1/bookings").set("Authorization", auth).send(booking).expect(201);

    const res = await request(app).post("/v1/bookings").set("Authorization", auth).send(booking);

    expect(res.status).toBe(409);
    expect(res.body.type).toBe("https://roombook.example/problems/booking-overlap");
  });

  it("answers 400 for a body that isn't JSON", async () => {
    const res = await request(testApp())
      .post("/v1/bookings")
      .set("Authorization", await bearer(ada))
      .set("Content-Type", "application/json")
      .send('{"roomId": 1,');

    expect(res.status).toBe(400);
    expect(res.body.type).toBe("https://roombook.example/problems/invalid-json");
  });
});

import { readFile } from "node:fs/promises";
import { migrate } from "../../scripts/migrate.ts";
import { createPool } from "../../src/db/pool.ts";

const url = process.env.TEST_DATABASE_URL;
if (!url || !new URL(url).pathname.endsWith("_test")) {
  throw new Error("Set TEST_DATABASE_URL to a database whose name ends in _test");
}

export const pool = createPool(url);

/** Run the migrations, then load the fixtures: the buildings, users, and rooms every test expects. */
export async function prepareDatabase() {
  await migrate(pool);
  await pool.query("TRUNCATE buildings, users, rooms, bookings RESTART IDENTITY CASCADE");
  await pool.query(await readFile(new URL("../fixtures/seed.sql", import.meta.url), "utf8"));
}

/** Empty the table tests write to, so each test starts from the fixtures alone. */
export async function resetBookings() {
  await pool.query("TRUNCATE bookings RESTART IDENTITY");
}

import request from "supertest";
import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";
import { ConflictError } from "../../src/domain/errors.ts";
import { createBookingRepository } from "../../src/modules/bookings/bookings.repository.ts";
import { createRoomRepository } from "../../src/modules/rooms/rooms.repository.ts";
import { ada, bearer, testApp } from "../support/app.ts";
import { pool, prepareDatabase, resetBookings } from "../support/db.ts";

const bookings = createBookingRepository(pool);

function at(start: string, end: string) {
  return { roomId: 1, userId: 1, startsAt: new Date(start), endsAt: new Date(end), attendees: 3, note: null };
}

beforeAll(prepareDatabase);
beforeEach(resetBookings);
afterAll(() => pool.end());

describe("the PostgreSQL booking repository", () => {
  it("saves a booking and reads it back", async () => {
    const saved = await bookings.insert(at("2026-10-05T14:00:00Z", "2026-10-05T15:30:00Z"));

    expect(saved).toMatchObject({ id: 1001, status: "confirmed", version: 1 });
    expect(await bookings.findById(saved.id)).toEqual(saved);
  });

  it("turns the exclusion constraint into a booking-overlap conflict", async () => {
    await bookings.insert(at("2026-10-05T14:00:00Z", "2026-10-05T15:30:00Z"));

    await expect(bookings.insert(at("2026-10-05T15:00:00Z", "2026-10-05T16:00:00Z"))).rejects.toThrow(ConflictError);
  });

  it("allows a booking that starts when the last one ends", async () => {
    await bookings.insert(at("2026-10-05T14:00:00Z", "2026-10-05T15:30:00Z"));

    await expect(bookings.insert(at("2026-10-05T15:30:00Z", "2026-10-05T16:00:00Z"))).resolves.toBeDefined();
  });
});

describe("two people booking the same slot at once", () => {
  it("lets exactly one of them win", async () => {
    const app = testApp({ rooms: createRoomRepository(pool), bookings });
    const auth = await bearer(ada);
    const body = { roomId: 1, startsAt: "2026-10-05T14:00:00Z", endsAt: "2026-10-05T15:30:00Z", attendees: 3 };

    const responses = await Promise.all(
      [1, 2].map(() => request(app).post("/v1/bookings").set("Authorization", auth).send(body)),
    );

    expect(responses.map((r) => r.status).sort()).toEqual([201, 409]);
  });
});

import { once } from "node:events";
import type { Server } from "node:http";
import type { AddressInfo } from "node:net";
import { afterAll, beforeAll, expect, test } from "vitest";
import { createApp } from "../../src/app.ts";
import { createAccessTokens } from "../../src/modules/auth/tokens.ts";
import { createUserDirectory } from "../../src/modules/auth/users.ts";
import { createBookingRepository } from "../../src/modules/bookings/bookings.repository.ts";
import { createBookingService } from "../../src/modules/bookings/bookings.service.ts";
import { createRoomRepository } from "../../src/modules/rooms/rooms.repository.ts";
import { clock, TEST_SECRET } from "../support/app.ts";
import { pool, prepareDatabase, resetBookings } from "../support/db.ts";

let server: Server;
let base: string;

beforeAll(async () => {
  await prepareDatabase();
  await resetBookings();
  const rooms = createRoomRepository(pool);
  const app = createApp({
    bookingService: createBookingService({ bookings: createBookingRepository(pool), rooms, clock }),
    rooms,
    users: createUserDirectory(),
    tokens: createAccessTokens(TEST_SECRET),
  });
  server = app.listen(0, "127.0.0.1"); // port 0: the system picks a free one
  await once(server, "listening");
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});

afterAll(async () => {
  server.close();
  await pool.end();
});

test("a member signs in, books a room, and reads the booking back", async () => {
  const login = await fetch(`${base}/v1/auth/token`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: "ada@roombook.example", password: "correct horse battery staple" }),
  });
  expect(login.status).toBe(200);
  const { accessToken } = await login.json();
  const auth = { Authorization: `Bearer ${accessToken}` };

  const created = await fetch(`${base}/v1/bookings`, {
    method: "POST",
    headers: { ...auth, "Content-Type": "application/json" },
    body: JSON.stringify({ roomId: 1, startsAt: "2026-10-05T14:00:00Z", endsAt: "2026-10-05T15:30:00Z", attendees: 3 }),
  });
  expect(created.status).toBe(201);

  const read = await fetch(base + created.headers.get("Location"), { headers: auth });
  expect(read.status).toBe(200);
  expect(await read.json()).toEqual(await created.json());
});
